import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DiAOIirN.js";var i=JSON.parse(`{"title":"What is imap-mcp?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1787780061000}`),a={name:`guide/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="what-is-imap-mcp" tabindex="-1">What is imap-mcp? <a class="header-anchor" href="#what-is-imap-mcp" aria-label="Permalink to “What is imap-mcp?”">​</a></h1><p>An MCP server for any IMAP mailbox: find the mail, read it, file it — with every message fenced as untrusted content and the write tools off unless you turn them on.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>A mailbox is the richest source of context most people have, and the most dangerous one to hand a model: every word in it was written by someone else. This server is built around that.</p><h2 id="what-it-is-not" tabindex="-1">What it is not <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to “What it is not”">​</a></h2><p>Sending mail. This server has no SMTP path at all, so no instruction found in a message can be carried out by it — which is what makes the untrusted-content framing worth anything.</p>`,6)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};